import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Exact own data keys only: no extras, no symbols, no accessors.
function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  if (own.length !== keys.length) return false;
  return keys.every(key => {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    return descriptor !== undefined && 'value' in descriptor;
  });
}

// Snapshot a dense array's elements; returns null for non-arrays or holes.
function denseElements(value) {
  if (!Array.isArray(value)) return null;
  const items = [];
  for (let index = 0; index < value.length; index += 1) {
    if (!Object.hasOwn(value, index)) return null;
    items.push(value[index]);
  }
  return items;
}

function isValidPath(relative) {
  if (typeof relative !== 'string' || relative.length === 0) return false;
  return relative.split('/').every(segment =>
    SEGMENT.test(segment) && !DEVICE_STEM.test(segment.split('.')[0]));
}

function parseManifest(manifest) {
  if (!isPlainObject(manifest) || !hasExactKeys(manifest, ['writes', 'deletes'])) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest must contain exactly writes and deletes');
  }
  const rawWrites = denseElements(manifest.writes);
  const rawDeletes = denseElements(manifest.deletes);
  if (rawWrites === null || rawDeletes === null) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest writes and deletes must be arrays');
  }
  const writes = rawWrites.map(item => {
    if (!isPlainObject(item) || !hasExactKeys(item, ['path', 'content']) ||
        typeof item.path !== 'string' || typeof item.content !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Each write must be exactly {path, content} strings');
    }
    return { path: item.path, content: item.content };
  });
  for (const item of rawDeletes) {
    if (typeof item !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Each delete must be a path string');
    }
  }
  const deletes = [...rawDeletes];

  const targets = [...writes.map(item => item.path), ...deletes];
  for (const target of targets) {
    if (!isValidPath(target)) throw fail('ERR_INVALID_PATH', `Invalid path: ${JSON.stringify(target)}`);
  }
  const unique = new Set(targets);
  if (unique.size !== targets.length) {
    throw fail('ERR_INVALID_MANIFEST', 'Duplicate manifest target');
  }
  for (const target of targets) {
    const segments = target.split('/');
    for (let length = 1; length < segments.length; length += 1) {
      if (unique.has(segments.slice(0, length).join('/'))) {
        throw fail('ERR_INVALID_MANIFEST', `Target ${target} is nested under another target`);
      }
    }
  }
  return { writes, deletes };
}

function parseGrants(grants) {
  const items = denseElements(grants);
  if (items === null) throw fail('ERR_INVALID_GRANT', 'Grants must be an array');
  const approved = new Set();
  for (const grant of items) {
    if (!isPlainObject(grant) || !hasExactKeys(grant, ['path', 'operation'])) {
      throw fail('ERR_INVALID_GRANT', 'Each grant must be exactly {path, operation}');
    }
    const { path: grantPath, operation } = grant;
    if (typeof operation !== 'string' || !OPERATIONS.has(operation) || !isValidPath(grantPath)) {
      throw fail('ERR_INVALID_GRANT', 'Invalid grant');
    }
    approved.add(`${operation}\0${grantPath}`);
  }
  return approved;
}

async function lstatOrNull(target) {
  try {
    return await fs.lstat(target);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

// Every existing component must be a real directory (ancestors) or regular file (leaf).
async function checkTarget(root, relative) {
  const segments = relative.split('/');
  let current = root;
  for (let index = 0; index < segments.length; index += 1) {
    current = path.join(current, segments[index]);
    const stats = await lstatOrNull(current);
    if (stats === null) return;
    const isLeaf = index === segments.length - 1;
    if (stats.isSymbolicLink() || (isLeaf ? !stats.isFile() : !stats.isDirectory())) {
      throw fail('ERR_UNSAFE_TARGET', `Unsafe target: ${relative}`);
    }
  }
}

export async function restore(directory, manifest, grants) {
  const { writes, deletes } = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const item of writes) {
    if (!approved.has(`write\0${item.path}`)) throw fail('ERR_DENIED', `Write not approved: ${item.path}`);
  }
  for (const relative of deletes) {
    if (!approved.has(`delete\0${relative}`)) throw fail('ERR_DENIED', `Delete not approved: ${relative}`);
  }

  const root = path.resolve(directory);
  const rootStats = await fs.lstat(root);
  if (rootStats.isSymbolicLink() || !rootStats.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Root must be a real directory');
  }
  for (const item of writes) await checkTarget(root, item.path);
  for (const relative of deletes) await checkTarget(root, relative);

  const written = [];
  const deleted = [];
  for (const item of writes) {
    const target = path.join(root, ...item.path.split('/'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, item.content, 'utf8');
    written.push(item.path);
  }
  for (const relative of deletes) {
    try {
      await fs.unlink(path.join(root, ...relative.split('/')));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }
  return { written, deleted };
}

